// @ts-check

/**
 * @file Shared contracts for editor state, uploads, and import feedback.
 * These describe existing data formats; numeric storage is shared with graph/types.js.
 */

/**
 * A column in source order: X first, then one column per series.
 * @typedef {Object} EditorColumn
 * @property {string} key Stable column identifier.
 * @property {string} name Display name from the header or generated by the parser.
 */

/**
 * Parser [type, data] entries, with source-record positions as defined in ADR-0007.
 * Keep the parser's existing diagnostic contract rather than inferring an empty array.
 * @typedef {NonNullable<ReturnType<typeof import('./state.js').parseDelimited>>['issues']} ImportIssues
 */

/**
 * Sample or legacy row storage when typed columns are absent.
 * @typedef {Object} RowData
 * @property {number[][]} rows X followed by Y values in each retained row.
 * @property {undefined} [numericColumns] No typed representation in this variant.
 */

/**
 * Typed storage from a file upload. It takes precedence if legacy rows also exist.
 * @typedef {Object} ColumnData
 * @property {NumericColumns} numericColumns Aligned X and Y columns. Uploads may
 * retain NaN for empty Y cells until the chart adapter applies the display policy.
 * @property {number[][]} [rows] Optional legacy rows, ignored when typed data exists.
 */

/**
 * Every dataset must provide rows or numericColumns; neither may be omitted together.
 * @typedef {(RowData|ColumnData)} EditorData
 */

/**
 * Column labels paired with parser diagnostics.
 * @typedef {Object} ImportMetadata
 * @property {EditorColumn[]} columns X column followed by Y columns.
 * @property {ImportIssues} issues Parser diagnostics, possibly empty.
 */

/**
 * Non-null input to import validation, supporting either existing data representation.
 * @typedef {EditorData & ImportMetadata} ParsedDataset
 */

/**
 * Uploaded fields consumed by App after validation succeeds. Parser metadata such
 * as delimiter and precision warnings may also be present on the original result.
 * @typedef {ColumnData & ImportMetadata & {sourceName: string}} AcceptedUpload
 */

/**
 * Supported editor plot types.
 * @typedef {('scatter'|'line')} EditorChartType
 */

/**
 * How the editor displays empty Y cells without rereading the file.
 * @typedef {('gap'|'zero'|'connect')} EmptyCellPolicy
 */

/**
 * A series style with its identity in the editor's source columns.
 * @typedef {SeriesStyle & {id: string, columnIndex: number, name: string}} EditorSeries
 */

/**
 * Presentation settings changed independently of the dataset.
 * @typedef {Object} EditorSettings
 * @property {EditorChartType} chartType Selected plot type.
 * @property {EmptyCellPolicy} emptyCells Policy applied by the chart adapter.
 * @property {EditorSeries[]} series Styles in Y-column order.
 * @property {string} title Chart title.
 * @property {string} subtitle Optional subtitle text.
 * @property {boolean} showSubtitle Whether to display the subtitle.
 * @property {string} xLabel Horizontal-axis label.
 * @property {string} yLabel Vertical-axis label.
 * @property {boolean} showPoints Whether line charts display markers.
 * @property {number} pointSize Marker size in logical chart units.
 */

/**
 * Fields needed to summarize a sample or uploaded dataset.
 * @typedef {EditorData & {sourceName: string, columns: EditorColumn[]}} DatasetSummaryInput
 */

/**
 * Full editor state, covering both sample rows and typed uploads with diagnostics.
 * @typedef {DatasetSummaryInput & EditorSettings & {parseIssues: ImportIssues}} EditorState
 */

/**
 * Changes made by presentation controls; dataset replacement uses AcceptedUpload.
 * @typedef {Partial<EditorSettings>} EditorSettingsPatch
 */
